"use client";

import { useMutation, useQuery } from "convex/react";
import { api } from "@convex/api";

export default function ProvidersPage() {
  const providers = useQuery(api.admin.listProviders);
  const toggle = useMutation(api.admin.toggleProvider);

  return (
    <div>
      <h1 style={{ fontSize: 24, fontWeight: 700, marginBottom: 20 }}>Providers</h1>
      <div className="card">
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Kind</th>
              <th>Platform</th>
              <th>Status</th>
              <th>Toggle</th>
            </tr>
          </thead>
          <tbody>
            {providers?.map((p) => (
              <tr key={p._id}>
                <td>{p.name}</td>
                <td><span className="badge badge-gray">{p.kind}</span></td>
                <td>{p.platform}</td>
                <td>
                  <span className={`badge ${p.enabled ? "badge-green" : "badge-red"}`}>
                    {p.enabled ? "Enabled" : "Disabled"}
                  </span>
                </td>
                <td>
                  <button
                    onClick={() => toggle({ providerId: p._id, enabled: !p.enabled })}
                    style={{
                      padding: "4px 12px",
                      borderRadius: 6,
                      border: "none",
                      background: p.enabled ? "#b91c1c" : "#15803d",
                      color: "#fff",
                      cursor: "pointer",
                      fontSize: 12,
                    }}
                  >
                    {p.enabled ? "Disable" : "Enable"}
                  </button>
                </td>
              </tr>
            ))}
            {(!providers || providers.length === 0) && (
              <tr><td colSpan={5} style={{ color: "#71717a", textAlign: "center", padding: 20 }}>No providers configured</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
